text=open('region.fasta').read()
seq=''.join(l.strip() for l in text.split('\n')[1:] if not l.startswith('>')).upper()
L=len(seq)
comp=str.maketrans('ACGT','TGCA')
rc=seq.translate(comp)[::-1]
bases='TCAG'; aas='FFLLSSSSYY**CC*WLLLLPPPPHHQQRRRRIIIMTTTTNNKKSSRRVVVVAAAADDEEGGGG'
codon={}; i=0
for a in bases:
 for b in bases:
  for c in bases:
   codon[a+b+c]=aas[i]; i+=1
def tr(s): return ''.join(codon[s[j:j+3]] for j in range(0,len(s)-2,3))

def find_orfs(s, strand):
    res=[]
    for f in range(3):
        i=f
        while i <= len(s)-3:
            if s[i:i+3]=='ATG':
                j=i
                while j<=len(s)-3 and s[j:j+3] not in ('TAA','TAG','TGA'):
                    j+=3
                if j<=len(s)-3:
                    ncod=(j+3-i)//3
                    if ncod>=100:
                        prot=tr(s[i:j+3])
                        # map to + coords
                        if strand=='+':
                            a,b=i+1,j+3
                        else:
                            a,b=L-(j+3)+1, L-i
                        res.append((a,b,ncod-1,strand,prot))
                i=j+3
            else:
                i+=3
    return res

orfs=find_orfs(seq,'+')+find_orfs(rc,'-')
orfs.sort(key=lambda x:-x[2])
print("Long ORFs (>=100 aa), + strand coordinates:")
for a,b,aa,st,prot in orfs:
    print(f"  {st} {a}-{b}  {aa} aa")
print()
# Show the repeat-containing ORF protein again
for a,b,aa,st,prot in orfs:
    if st=='+' and a<1900<b:
        print("ORF",a,b,"protein:")
        print(" ",prot)
